"""Build the offline final-data explorer using only the Python standard library."""
from __future__ import annotations

import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def build(source: Path, scope: Path, output: Path) -> None:
    metadata = json.loads((source / "metadata.json").read_text(encoding="utf-8"))
    names = metadata["generated_files"]
    if len(names) != len(set(names)) or any(Path(n).name != n for n in names):
        raise ValueError("Invalid generated file manifest")
    files = {name: (source / name).read_bytes().decode("utf-8") for name in names}
    entries = json.loads(scope.read_text(encoding="utf-8"))["entries"]
    payload = json.dumps({"files": files, "scope_entries": entries}, ensure_ascii=False)
    # Script elements are raw-text HTML; escape delimiters before embedding JSON.
    payload = payload.replace("<", "\\u003c").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(TEMPLATE.replace("__DATA_PAYLOAD__", payload), encoding="utf-8")
    print(f"Built {output}: {len(entries)} requirements; {len(files)} original source files")


TEMPLATE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Annotation Atlas · Five-model final data</title>
<style>
:root{--ink:#142d43;--muted:#54697b;--line:#d9e3e9;--paper:#fff;--bg:#f3f6f8;--teal:#007b73;--mint:#e4f4ef;--coral:#b64239;--rose:#fff0ed;--amber:#886000;--gold:#fff4d5}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input,select{font:inherit}button,select{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible,a:focus-visible{outline:3px solid #009aab;outline-offset:3px}button{border:1px solid var(--line);border-radius:8px;padding:8px 13px;background:#fff;color:var(--ink)}button:hover{border-color:var(--teal)}button:disabled{opacity:.45;cursor:default}a{color:var(--teal)}header{padding:28px max(24px,calc((100vw - 1600px)/2));background:var(--ink);color:white}.eyebrow{text-transform:uppercase;letter-spacing:.16em;font-size:11px;font-weight:700;color:#9ad8d1}h1{font-size:30px;letter-spacing:-.04em;margin:6px 0}header p{color:#c7d9e4;margin:5px 0 18px;max-width:800px}.header-line,.toolbar,.row,.record-top{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.header-line{justify-content:space-between}.metrics{display:flex;gap:28px;flex-wrap:wrap}.metric strong{font-size:26px;font-weight:650;display:block}.metric span{font-size:12px;color:#bed2dd}.shell{max-width:1648px;padding:24px;margin:auto}.toolbar{justify-content:space-between;margin-bottom:18px}.segmented{display:flex;gap:4px;background:#e7edf1;padding:4px;border-radius:11px}.segmented button{border:0;background:transparent}.segmented button[aria-pressed=true]{background:white;box-shadow:0 1px 4px #1232;font-weight:650}.layout{display:grid;grid-template-columns:300px minmax(0,1fr);gap:24px}.sidebar,.panel,.card{background:var(--paper);border:1px solid var(--line);border-radius:12px}.sidebar{align-self:start;position:sticky;top:16px;overflow:hidden}.filters{padding:16px;display:grid;gap:8px}.filters label,.small-label{font-size:12px;font-weight:650;color:var(--muted)}input,select{width:100%;padding:10px;border:1px solid #c4d2dc;border-radius:7px;background:white;color:var(--ink)}#matchCount{font-size:12px;color:var(--muted);padding:0 16px 12px}.record-list{max-height:65vh;overflow:auto;border-top:1px solid var(--line)}.record-link{display:block;border:0;border-radius:0;border-bottom:1px solid #edf1f4;width:100%;text-align:left;padding:13px 16px;background:white}.record-link[aria-current=true]{background:#e9f5f2;box-shadow:inset 3px 0 var(--teal)}.record-link strong{font-size:12px}.record-link .preview{display:block;font-size:13px;margin-top:5px;white-space:normal;overflow-wrap:anywhere}.record-link .family{display:block;font-size:11px;color:var(--muted);margin-top:5px}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--teal);margin-right:5px}.dot.excluded{background:var(--coral)}.panel{padding:25px;min-width:0}.record-top{justify-content:space-between}.badge{display:inline-block;border-radius:5px;padding:3px 8px;font-size:12px;font-weight:650;background:#eaf0f4;color:var(--muted)}.badge.good{background:var(--mint);color:var(--teal)}.badge.bad{background:var(--rose);color:var(--coral)}.badge.warn{background:var(--gold);color:var(--amber)}h2{font-size:23px;margin:14px 0 7px;letter-spacing:-.02em}h3{font-size:17px;margin:0 0 12px}h4{font-size:13px;margin:18px 0 7px;color:var(--muted)}p{margin:6px 0 12px}.muted{color:var(--muted)}.requirement{font-size:21px;line-height:1.5;margin:18px 0}.propositions{display:flex;gap:8px;flex-wrap:wrap}.prop{background:var(--bg);border-radius:6px;padding:6px 10px}.prop code{color:var(--teal);font-weight:700}.notice{padding:13px 16px;border-left:3px solid var(--coral);background:var(--rose);margin:16px 0}.tabs{display:flex;gap:6px;border-bottom:1px solid var(--line);padding-bottom:10px;margin:24px 0;flex-wrap:wrap}.tabs button[aria-pressed=true]{background:var(--ink);color:white;border-color:var(--ink)}.card{padding:20px;margin-bottom:16px}.reading-title{display:flex;justify-content:space-between;gap:12px;align-items:start}.bar{display:flex;height:9px;border-radius:5px;overflow:hidden;background:#eef2f4;margin:16px 0 7px}.bar span{height:100%}.supported{background:var(--teal)}.unsupported{background:var(--coral)}.uncertain{background:#d4a12c}.legend{font-size:12px;display:flex;gap:15px;flex-wrap:wrap;color:var(--muted)}.swatch{width:8px;height:8px;display:inline-block;margin-right:5px;border-radius:2px}.votes{display:grid;grid-template-columns:minmax(150px,1fr) auto;gap:8px 16px;margin-top:16px;font-size:13px}.votes span{overflow-wrap:anywhere}.interpretations{padding-left:22px}.interpretations li{padding-left:4px;margin:9px 0}.model-name{overflow-wrap:anywhere;font-size:16px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.grid>.card{margin:0}details{border-top:1px solid var(--line);margin-top:15px;padding-top:12px}summary{cursor:pointer;font-weight:650;font-size:13px}.field-value{white-space:pre-wrap;overflow-wrap:anywhere}pre{font:12px/1.65 ui-monospace,SFMono-Regular,Consolas,monospace;background:#f4f7f9;border:1px solid var(--line);padding:16px;border-radius:8px;white-space:pre-wrap;overflow-wrap:anywhere;margin-bottom:0}.empty{font:12px ui-monospace,monospace;color:var(--muted);background:var(--bg);padding:2px 5px;border-radius:4px}.member{padding:12px 0;border-top:1px solid #edf1f4}.member:first-child{border:0}.member p{margin:5px 0}.source-section{margin-top:28px}.source-section>summary{font-size:17px}.source-controls{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;margin:16px 0}footer{font-size:12px;color:var(--muted);padding:20px 0}#emptyState{padding:40px;text-align:center}button.primary{background:var(--teal);border-color:var(--teal);color:white}.sr-only{position:absolute;left:-10000px;width:1px;height:1px;overflow:hidden}ul{padding-left:20px}code{overflow-wrap:anywhere}.source-note{font-size:12px;color:var(--muted)}
@media(max-width:1050px){.layout{grid-template-columns:250px minmax(0,1fr)}.grid{grid-template-columns:1fr}.panel{padding:20px}.shell{padding:16px}}@media(max-width:700px){header{padding:23px 18px}h1{font-size:27px}.metrics{gap:20px}.metric strong{font-size:23px}.layout{grid-template-columns:1fr;gap:16px}.sidebar{position:static}.record-list{max-height:230px}.filters{grid-template-columns:1fr 1fr}.filters label{display:block}.filters input,.filters select{margin-top:4px}.panel{padding:17px}.requirement{font-size:19px}.toolbar{gap:14px}.source-controls{grid-template-columns:1fr}.votes{grid-template-columns:minmax(0,1fr) auto}}
</style></head><body>
<header><div class="header-line"><div><div class="eyebrow">Five-model annotation · Final release</div><h1>Annotation Atlas</h1><p>Explore every requirement, interpretation and model decision. Follow the consensus back to the original responses and source values.</p></div><button id="downloadDataset" class="primary">Download final dataset ↓</button></div><div class="metrics" id="metrics"></div></header>
<main class="shell"><div class="toolbar"><div class="segmented" aria-label="Requirement population"><button data-mode="final" aria-pressed="true">Final <span id="finalCount"></span></button><button data-mode="excluded" aria-pressed="false">Excluded <span id="excludedCount"></span></button><button data-mode="all" aria-pressed="false">All <span id="allCount"></span></button></div><span class="source-note" id="rule"></span></div>
<div class="layout"><aside class="sidebar" aria-label="Requirement browser"><div class="filters"><label>Search every record value<input id="search" type="search" placeholder="Text, ID, model, comment…"></label><label>Source family<select id="family"><option value="">All families</option></select></label></div><div id="matchCount" role="status" aria-live="polite"></div><nav id="recordList" class="record-list" aria-label="Requirements"></nav></aside><section id="recordPanel" class="panel" aria-label="Selected requirement"></section></div>
<details class="panel source-section" id="sources"><summary>Source files &amp; global provenance · <span id="sourceCount"></span> original files</summary><p class="muted">Every exported value is preserved here. Downloads contain the original UTF-8 source text, including empty family files. The frozen scope entries are also available below.</p><div class="source-controls"><label>Original exported file<select id="sourceFile"></select></label><button id="downloadSource">Download selected file ↓</button></div><div id="sourceInfo" class="source-note"></div><pre id="sourceText" tabindex="0" aria-label="Original source file text"></pre><details><summary>Global metadata and input SHA-256 provenance</summary><pre id="metadataText"></pre></details><details><summary>All frozen scope entries · original values</summary><pre id="scopeText"></pre></details></details>
<footer>Offline, self-contained viewer · No network requests or model calls. Stage 2 additions never count as independent Stage 1 votes. Excluded requirements are shown for audit and are absent from the final dataset.</footer></main>
<script type="application/json" id="data">__DATA_PAYLOAD__</script>
<script>
'use strict';
const payload=JSON.parse(document.getElementById('data').textContent), files=payload.files;
const rows=name=>files[name].split(/\r?\n/).filter(line=>line.trim()).map(line=>JSON.parse(line));
const metadata=JSON.parse(files['metadata.json']), models=metadata.expected_models;
const finals=rows('dataset.jsonl'), audits=rows('vote_summary.jsonl'), additions=rows('stage2_additional_interpretations.jsonl');
const byId=items=>new Map(items.map(item=>[item.review_id,item]));
const finalMap=byId(finals), auditMap=byId(audits);
const records=payload.scope_entries.map(scope=>({scope,final:finalMap.get(scope.review_id)||null,audit:auditMap.get(scope.review_id),annotations:additions.filter(a=>a.review_id===scope.review_id)}));
const $=id=>document.getElementById(id), esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=value=>JSON.stringify(value,null,2), raw=value=>`<pre>${esc(json(value))}</pre>`;
const value=v=>v===''?'<span class="empty">"" (empty string)</span>':v===undefined?'<span class="empty">Not present in source</span>':v===null?'<span class="empty">null</span>':typeof v==='object'?raw(v):`<span class="field-value">${esc(v)}</span>`;
const list=items=>items.length?`<ol class="interpretations">${items.map(i=>`<li>${value(i)}</li>`).join('')}</ol>`:'<span class="empty">[] (empty list)</span>';
const shortModel=model=>model.split('/').pop();
const badge=label=>`<span class="badge ${label==='Supported'?'good':label==='Not supported'?'bad':'warn'}">${label===null?'Unresolved (null)':esc(label)}</span>`;
let mode='final',selected=records.find(r=>r.final)?.scope.review_id, tab='consensus', visible=[];
const searchable=new Map(records.map(r=>[r.scope.review_id,JSON.stringify(r).toLowerCase()]));
$('metrics').innerHTML=[[records.length,'source requirements'],[finals.length,'retained in final'],[records.length-finals.length,'excluded & audited'],[models.length,'independent models'],[audits.reduce((n,a)=>n+a.groups.reduce((m,g)=>m+g.members.length,0),0),'original interpretations']].map(([n,label])=>`<div class="metric"><strong>${n}</strong><span>${label}</span></div>`).join('');
$('finalCount').textContent=finals.length;$('excludedCount').textContent=records.length-finals.length;$('allCount').textContent=records.length;
$('rule').textContent=`Threshold ${metadata.min_agreeing_models} of ${metadata.population} models · unique highest label required`;
[...new Set(records.map(r=>r.scope.source_family))].sort().forEach(f=>{const option=document.createElement('option');option.value=f;option.textContent=f;$('family').append(option)});
function filterRecords(){const query=$('search').value.toLowerCase().trim(),family=$('family').value;visible=records.filter(r=>(mode==='all'||(mode==='final'?Boolean(r.final):!r.final))&&(!family||r.scope.source_family===family)&&(!query||searchable.get(r.scope.review_id).includes(query)));if(!visible.some(r=>r.scope.review_id===selected))selected=visible[0]?.scope.review_id;renderList();renderRecord()}
function renderList(){ $('matchCount').textContent=`${visible.length} matching requirement${visible.length===1?'':'s'} · ${mode==='all'?'all records':mode==='final'?'final dataset':'excluded audit'}`;$('recordList').innerHTML=visible.map(r=>`<button class="record-link" data-id="${esc(r.scope.review_id)}" aria-current="${r.scope.review_id===selected}"><strong><span class="dot ${r.final?'':'excluded'}"></span>${esc(r.scope.review_id)} · ${r.final?'Final':'Excluded'}</strong><span class="preview">${esc(r.scope.requirement)}</span><span class="family">${esc(r.scope.source_family)} · ${esc(r.scope.annotation_id)}</span></button>`).join('')}
function readingsView(r){return r.scope.readings.map(reading=>{const vote=r.audit.readings.find(v=>v.reading_id===reading.reading_id);return `<article class="card"><div class="reading-title"><h3>Reading ${esc(reading.reading_id)}</h3>${badge(vote.label)}</div><p class="field-value">${esc(reading.plain)}</p><div class="bar" role="img" aria-label="${esc(Object.entries(vote.counts).map(([label,count])=>`${label}: ${count}`).join(', '))}">${[['Supported','supported'],['Not supported','unsupported'],['Uncertain','uncertain']].map(([label,cls])=>`<span class="${cls}" style="width:${vote.counts[label]/models.length*100}%"></span>`).join('')}</div><div class="legend">${[['Supported','supported'],['Not supported','unsupported'],['Uncertain','uncertain']].map(([label,cls])=>`<span><i class="swatch ${cls}"></i>${esc(label)} ${vote.counts[label]}/${models.length}</span>`).join('')}</div><div class="votes">${models.map(model=>`<span title="${esc(model)}">${esc(model)}</span><span>${badge(vote.responses[model])}</span>`).join('')}</div></article>`}).join('')}
function modelData(r,model){const annotation=r.annotations.find(a=>a.model===model);return {model,stage1_interpretations:r.audit.groups.flatMap(g=>g.members.filter(m=>m.model===model).map(m=>({...m,group_id:g.group_id}))).sort((a,b)=>a.interpretation_index-b.interpretation_index),stage1_comments:annotation.stage1_comments,stage2_readings:r.audit.readings.map(v=>({reading_id:v.reading_id,label:v.responses[model]})),stage2_annotation:annotation}}
function modelsView(r){return `<p class="muted">Original Stage 1 wording is reconstructed from exact group memberships in its original index order. Reading labels and additions come from Stage 2.</p><div class="grid">${models.map(model=>{const d=modelData(r,model);return `<article class="card"><h3 class="model-name">${esc(model)}</h3><h4>Stage 1 · ${d.stage1_interpretations.length} original interpretations</h4>${d.stage1_interpretations.length?`<ol class="interpretations">${d.stage1_interpretations.map(m=>`<li value="${m.interpretation_index+1}"><div class="field-value">${esc(m.text)}</div><small class="muted">Original index ${m.interpretation_index} · ${esc(m.group_id)}</small></li>`).join('')}</ol>`:list([])}<h4>Stage 1 comments</h4>${value(d.stage1_comments)}<h4>Stage 2 · reading assessments</h4><div class="votes">${d.stage2_readings.map(v=>`<span>Reading ${esc(v.reading_id)}</span><span>${badge(v.label)}</span>`).join('')}</div><h4>Stage 2 additions <span class="badge warn">Not Stage 1 votes</span></h4>${list(d.stage2_annotation.additional_interpretations)}<h4>Stage 2 comments</h4>${value(d.stage2_annotation.comments)}<details><summary>All values for this model</summary>${raw(d)}</details></article>`}).join('')}</div>`}
function groupsView(r){return `<p class="muted">${r.audit.groups.length} reviewed semantic groups. Each model counts once per group, including repeated paraphrases. The threshold is ${metadata.min_agreeing_models}/${metadata.population}.</p>${r.audit.groups.map(g=>`<article class="card"><div class="reading-title"><h3>${esc(g.group_id)}</h3><span class="badge ${g.retained?'good':'bad'}">${g.retained?'Retained':'Below threshold'} · ${g.model_count}/${models.length}</span></div><p class="field-value">${esc(g.canonical)}</p><h4>Grouping explanation</h4>${value(g.explanation)}<h4>Original members · ${g.members.length} interpretations, ${g.model_count} models</h4>${g.members.map(m=>`<div class="member"><small class="muted">${esc(m.model)} · original index ${m.interpretation_index}</small><p class="field-value">${esc(m.text)}</p></div>`).join('')}<details><summary>All group fields</summary>${raw(g)}</details></article>`).join('')}`}
function allView(r){return `<p class="muted">Complete structured values, including empty strings, lists, false, zero and provenance hashes.</p>${r.final?`<details open><summary>Final dataset record · original exported object</summary>${raw(r.final)}</details>`:'<div class="notice">No final dataset record exists for this excluded requirement. Its original scope and audits are below.</div>'}<details open><summary>Frozen scope entry</summary>${raw(r.scope)}</details><details><summary>Complete vote and grouping audit</summary>${raw(r.audit)}</details><details><summary>All five Stage 2 annotations, including Stage 1 comments</summary>${raw(r.annotations)}</details><details><summary>All reconstructed model results</summary>${raw(models.map(m=>modelData(r,m)))}</details>`}
function renderRecord(){const r=records.find(r=>r.scope.review_id===selected);if(!r){$('recordPanel').innerHTML='<div id="emptyState"><h2>No matching requirements</h2><p class="muted">Change the search, family or population filter to explore more records.</p></div>';return}const index=visible.indexOf(r);$('recordPanel').innerHTML=`<div class="record-top"><div class="row"><span class="badge ${r.final?'good':'bad'}">${r.final?'Final dataset':'Excluded · audit only'}</span><strong>${esc(r.scope.review_id)}</strong><span class="muted">${esc(r.scope.annotation_id)}</span></div><div class="row"><button id="previous" ${index<=0?'disabled':''} aria-label="Previous requirement">←</button><span class="source-note">${index+1} / ${visible.length}</span><button id="next" ${index>=visible.length-1?'disabled':''} aria-label="Next requirement">→</button></div></div><h2>${esc(r.scope.source_family.replaceAll('_',' '))}</h2><p class="requirement field-value">${esc(r.scope.requirement)}</p><div class="propositions">${Object.entries(r.scope.propositions).map(([k,v])=>`<span class="prop"><code>${esc(k)}</code> · ${esc(v)}</span>`).join('')}</div>${Object.hasOwn(r.scope,'scenario')?`<h4>Scenario</h4>${value(r.scope.scenario)}`:''}${!r.final?`<div class="notice"><strong>Excluded from the final dataset</strong><ul>${r.audit.exclusion_reasons.map(reason=>`<li>${esc(reason)}</li>`).join('')}</ul></div>`:''}<div class="tabs" aria-label="Record views">${[['consensus','Consensus & readings'],['models','Five model results'],['groups','Semantic groups'],['all','Every field']].map(([id,label])=>`<button data-tab="${id}" aria-pressed="${tab===id}">${label}</button>`).join('')}</div><div id="tabContent">${tab==='consensus'?`<h3>Retained Stage 1 meanings</h3>${list(r.audit.groups.filter(g=>g.retained).map(g=>g.canonical))}<h3 style="margin-top:26px">Reading consensus</h3>${readingsView(r)}`:tab==='models'?modelsView(r):tab==='groups'?groupsView(r):allView(r)}</div><button id="downloadRecord">Download ${r.final?'final record':'audit bundle'} ↓</button>`;
$('previous').onclick=()=>navigate(-1);$('next').onclick=()=>navigate(1);$('downloadRecord').onclick=()=>download(`${selected}${r.final?'.json':'.audit.json'}`,json(r.final||{scope:r.scope,audit:r.audit,annotations:r.annotations}), 'application/json');
}
function navigate(offset){const index=visible.findIndex(r=>r.scope.review_id===selected);selectRecord(visible[index+offset]?.scope.review_id)}
function selectRecord(id){if(!id)return;selected=id;history.replaceState(null,'',`#${encodeURIComponent(id)}`);renderList();renderRecord()}
function download(name,text,type='application/x-ndjson'){const blob=new Blob([text],{type:`${type};charset=utf-8`}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('recordList').onclick=e=>{const b=e.target.closest('[data-id]');if(b)selectRecord(b.dataset.id)};
$('recordPanel').onclick=e=>{const b=e.target.closest('[data-tab]');if(b){tab=b.dataset.tab;renderRecord();$('recordPanel').querySelector(`[data-tab="${tab}"]`).focus()}};
document.querySelectorAll('[data-mode]').forEach(button=>button.onclick=()=>{mode=button.dataset.mode;document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));filterRecords()});
$('search').oninput=filterRecords;$('family').onchange=filterRecords;
$('downloadDataset').onclick=()=>download('dataset.jsonl',files['dataset.jsonl']);
$('sourceCount').textContent=Object.keys(files).length;
Object.keys(files).forEach(name=>{const option=document.createElement('option');option.value=name;option.textContent=name;$('sourceFile').append(option)});
function renderSource(){const name=$('sourceFile').value,text=files[name];$('sourceText').textContent=text||'(empty file · 0 bytes)';$('sourceInfo').textContent=`${name} · ${new TextEncoder().encode(text).length.toLocaleString()} UTF-8 bytes · original text, no transformation`}
$('sourceFile').onchange=renderSource;$('downloadSource').onclick=()=>download($('sourceFile').value,files[$('sourceFile').value],$('sourceFile').value.endsWith('.json')?'application/json':'application/x-ndjson');
$('metadataText').textContent=json(metadata);$('scopeText').textContent=json(payload.scope_entries);
let hashId='';try{hashId=decodeURIComponent(location.hash.slice(1))}catch(error){if(!(error instanceof URIError))throw error}if(records.some(r=>r.scope.review_id===hashId)){selected=hashId;if(!finalMap.has(hashId)){mode='all';document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)))}}
filterRecords();renderSource();
</script></body></html>
'''


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=Path, default=ROOT / "annotation_final/five_model_v1")
    parser.add_argument("--scope", type=Path, default=ROOT / "annotation_runs/five_model_v1/scope.json")
    parser.add_argument("--output", type=Path, default=ROOT / "annotation_final/explorer.html")
    args = parser.parse_args()
    if args.output.resolve().is_relative_to(args.source.resolve()):
        parser.error("Keep the viewer outside the generated dataset directory")
    build(args.source, args.scope, args.output)


if __name__ == "__main__":
    main()
